const weight = query.weight_kg;
const heightCm = query.height_cm;

// Validate inputs
if (
typeof weight !== "number" ||
typeof heightCm !== "number" ||
weight <= 0 ||
heightCm <= 0
) {
return {
error: "Weight and height must be positive numbers."
};
}

// Convert height from centimeters to meters
const heightM = heightCm / 100;

// Calculate BMI
const bmi = weight / Math.pow(heightM, 2);

// Determine BMI category
let category;

if (bmi < 18.5) {
category = "Underweight";
} else if (bmi < 25) {
category = "Normal weight";
} else if (bmi < 30) {
category = "Overweight";
} else {
category = "Obesity";
}

// Prepare result
const result = {
status: "success",
weight_kg: weight,
height_cm: heightCm,
bmi: Number(bmi.toFixed(1)),
category: category
};

return JSON.stringify(result);

const systolic = query.systolic;
const diastolic = query.diastolic;

// Validate inputs
if (
typeof systolic !== "number" ||
typeof diastolic !== "number" ||
systolic <= 0 ||
diastolic <= 0
) {
return {
error: "Systolic and diastolic blood pressure must be positive numbers."
};
}

let category;
let explanation;

// Grade 3 Hypertension
if (systolic >= 180 || diastolic >= 110) {
category = "Grade 3 Hypertension";
explanation = "Systolic blood pressure is >=180 mmHg or diastolic blood pressure is >=110 mmHg.";
}

// Grade 2 Hypertension
else if (systolic >= 160 || diastolic >= 100) {
category = "Grade 2 Hypertension";
explanation = "Systolic blood pressure is 160-179 mmHg or diastolic blood pressure is 100-109 mmHg.";
}

// Grade 1 Hypertension
else if (systolic >= 140 || diastolic >= 90) {
category = "Grade 1 Hypertension";
explanation = "Systolic blood pressure is 140-159 mmHg or diastolic blood pressure is 90-99 mmHg.";
}

// Isolated Systolic Hypertension
else if (systolic >= 140 && diastolic < 90) {
category = "Isolated Systolic Hypertension";
explanation = "Systolic blood pressure is >=140 mmHg while diastolic blood pressure is <90 mmHg.";
}

// High Normal
else if (systolic >= 130 || diastolic >= 85) {
category = "High Normal";
explanation = "Systolic blood pressure is 130-139 mmHg or diastolic blood pressure is 85-89 mmHg.";
}

// Normal
else if (systolic >= 120 || diastolic >= 80) {
category = "Normal";
explanation = "Systolic blood pressure is 120-129 mmHg or diastolic blood pressure is 80-84 mmHg.";
}

// Optimal
else {
category = "Optimal";
explanation = "Systolic blood pressure is <120 mmHg and diastolic blood pressure is <80 mmHg.";
}

const result = {
systolic_mmhg: systolic,
diastolic_mmhg: diastolic,
category: category,
explanation: explanation
};

return JSON.stringify(result);

const readings = query.readings;

// Validate that readings exist and are an array
if (!Array.isArray(readings) || readings.length < 2) {
return {
error: "At least two blood pressure readings are required."
};
}

// Validate each reading
for (const reading of readings) {
if (
typeof reading.systolic !== "number" ||
typeof reading.diastolic !== "number"
) {
return {
error: "Each reading must contain numeric systolic and diastolic values."
};
}

if (
reading.systolic <= 0 ||
reading.diastolic <= 0
) {
return {
error: "Systolic and diastolic values must be positive numbers."
};
}
}

// Calculate averages
const totalSystolic = readings.reduce(
(sum, reading) => sum + reading.systolic,
0
);

const totalDiastolic = readings.reduce(
(sum, reading) => sum + reading.diastolic,
0
);

const averageSystolic = totalSystolic / readings.length;
const averageDiastolic = totalDiastolic / readings.length;

// Prepare result
const result = {
status: "success",
readings_count: readings.length,
average_systolic: Number(averageSystolic.toFixed(1)),
average_diastolic: Number(averageDiastolic.toFixed(1))
};

return JSON.stringify(result);

const hba1c = query.hba1c;

// Validate input
if (
typeof hba1c !== "number" ||
!Number.isFinite(hba1c)
) {
return {
error: "HbA1c must be a valid number."
};
}

// Validate reasonable range
if (hba1c < 0 || hba1c > 100) {
return {
error: "HbA1c value must be between 0 and 100%."
};
}

let category;
let explanation;

// Normal
if (hba1c < 5.7) {
category = "Normal";
explanation = "HbA1c is below 5.7%.";

// Prediabetes
} else if (hba1c >= 5.7 && hba1c < 6.5) {
category = "Prediabetes";
explanation = "HbA1c is between 5.7% and 6.4%.";

// Controlled Diabetes
} else if (hba1c >= 6.5 && hba1c <= 7.0) {
category = "Controlled Diabetes";
explanation = "HbA1c is between 6.5% and 7.0%.";

// Uncontrolled Diabetes
} else {
category = "Uncontrolled Diabetes";
explanation = "HbA1c is above 7.0%.";
}

const result = {
hba1c_percent: hba1c,
category: category,
explanation: explanation
};

return JSON.stringify(result);

