const MAX_TOKENS = 4000;
const MAX_CHARS = MAX_TOKENS * 4; // 16,000 حرف

// 1. استخراج النص بدقة من رسالة تليجرام
const inputItem = $input.first().json;
const userText = 
  (inputItem.message && typeof inputItem.message.text === 'string' ? inputItem.message.text : null) ||
  (inputItem.text && typeof inputItem.text.text === 'string' ? inputItem.text.text : null) ||
  (typeof inputItem.text === 'string' ? inputItem.text : null) ||
  inputItem.content || 
  inputItem.chatInput || 
  "";

// 2. حساب عدد الحروف والتوكنات بدقة
const totalChars = userText.length;
const estimatedTokens = Math.ceil(totalChars / 4);

let processedText = userText;
let isExceeded = false;

// 3. التحقق مما إذا كان النص يتجاوز الحد الأقصى (16 ألف حرف / 4000 توكن)
if (estimatedTokens > MAX_TOKENS) {
    isExceeded = true;
    processedText = userText.substring(0, MAX_CHARS);
}

return [{
    json: {
        ...inputItem,
        ...(inputItem.message ? { message: { ...inputItem.message, text: processedText } } : {}),
        text: processedText,
        token_control: {
            total_characters: totalChars,
            estimated_tokens: estimatedTokens,
            max_allowed_tokens: MAX_TOKENS,
            exceeded: isExceeded,
            status: isExceeded ? "truncated_due_to_token_limit" : "within_limit"
        }
    }
}];

// تحديد الحد الأقصى لمدّة الصوت بالثواني (90 ثانية)
const MAX_DURATION_SECONDS = 360;

// استخراج بيانات الرسالة من تليجرام
const inputItem = $input.first().json;

// التحقق مما إذا كانت الرسالة تحتوي على صوت (Voice) أو ملف صوتي (Audio)
const voiceMessage = inputItem.message?.voice || inputItem.message?.audio;
const duration = voiceMessage ? voiceMessage.duration : 0; // المدة بالثواني
const fileSize = voiceMessage ? voiceMessage.file_size : 0; // حجم الملف بالبايت

let isAllowed = true;
let rejectionReason = null;

if (voiceMessage) {
    if (duration > MAX_DURATION_SECONDS) {
        isAllowed = false;
        rejectionReason = `Voice message duration (${duration}s) exceeds the maximum allowed limit of ${MAX_DURATION_SECONDS} seconds.`;
    }
}

return [{
    json: {
        ...inputItem,
        voice_control: {
            is_voice: !!voiceMessage,
            duration_seconds: duration,
            max_allowed_seconds: MAX_DURATION_SECONDS,
            file_size_bytes: fileSize,
            allowed: isAllowed,
            reason: rejectionReason,
            status: isAllowed ? "voice_within_limit" : "voice_too_long"
        }
    }
}];

const items = $input.all();

// ============================================================
// 1. GET ORIGINAL TEXT
//    No dependency on "When chat message received"
// ============================================================

let originalText = "";

// First: get original text from Regex detect
try {
  originalText =
    $('Regex detect').first().json.guardrailsInput || "";
} catch (e) {}

// Second: try Guardrails
if (!originalText) {
  try {
    originalText =
      $('Guardrails').first().json.guardrailsInput || "";
  } catch (e) {}
}

// Third: try current input items
if (!originalText) {
  for (const item of items) {
    if (item.json?.guardrailsInput) {
      originalText = item.json.guardrailsInput;
      break;
    }
  }
}

if (!originalText) {
  throw new Error("Original text not found.");
}


// ============================================================
// 2. VARIABLES
// ============================================================

let mapping = {};
let counters = {};
let allEntities = [];


// ============================================================
// 3. GET GUARDRAILS / REGEX RESULTS
// ============================================================

try {

  const guardrailsData =
    $('Regex detect').first().json;

  const analyzerResults =
    guardrailsData?.checks?.[0]?.info?.analyzerResults;

  if (Array.isArray(analyzerResults)) {

    for (const item of analyzerResults) {

      if (!item?.text) continue;

      const entityText = String(item.text);

      const start =
        originalText.indexOf(entityText);

      if (start !== -1) {

        allEntities.push({
          entity_type:
            item.entityType || "PII",

          text:
            entityText,

          start:
            start,

          end:
            start + entityText.length,

          source:
            "guardrails"
        });
      }
    }
  }

} catch (err) {
  // Ignore Guardrails errors
}


// ============================================================
// 4. GET PRESIDIO RESULTS
// ============================================================

for (const item of items) {

  const data = item.json;

  if (
    data &&
    typeof data.start === "number" &&
    typeof data.end === "number"
  ) {

    const start = data.start;
    const end = data.end;

    const textVal =
      originalText.substring(start, end);

    if (textVal) {

      allEntities.push({
        entity_type:
          data.entity_type || "PII",

        text:
          textVal,

        start:
          start,

        end:
          end,

        source:
          "presidio"
      });
    }
  }
}


// ============================================================
// 5. FILTER ENTITIES
// ============================================================

allEntities =
  allEntities.filter(entity => {

    const type =
      String(entity.entity_type || "")
        .toUpperCase()
        .trim();


    // --------------------------------------------------------
    // KEEP EMAIL VISIBLE
    // --------------------------------------------------------

    if (
      type === "EMAIL" ||
      type === "EMAIL_ADDRESS" ||
      type === "EMAILADDRESS"
    ) {
      return false;
    }


    // --------------------------------------------------------
    // KEEP URL VISIBLE IF IT IS PART OF AN EMAIL
    // --------------------------------------------------------

    if (
      type === "URL" ||
      type === "URI"
    ) {

      const before =
        originalText.substring(
          Math.max(0, entity.start - 100),
          entity.start
        );

      const current =
        originalText.substring(
          entity.start,
          entity.end
        );

      const after =
        originalText.substring(
          entity.end,
          Math.min(
            originalText.length,
            entity.end + 100
          )
        );

      const surroundingText =
        before + current + after;

      const emailRegex =
        /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i;

      if (
        emailRegex.test(surroundingText)
      ) {
        return false;
      }
    }


    return true;
  });


// ============================================================
// 6. REMOVE DUPLICATES / OVERLAPPING ENTITIES
// ============================================================

allEntities.sort(
  (a, b) =>
    b.start - a.start ||
    (b.end - b.start) -
    (a.end - a.start)
);


let filteredEntities = [];

for (const entity of allEntities) {

  const overlap =
    filteredEntities.some(e =>
      entity.start < e.end &&
      entity.end > e.start
    );

  if (!overlap) {
    filteredEntities.push(entity);
  }
}


// ============================================================
// 7. CREATE TOKENS + MAPPING
// ============================================================

let modifiedText =
  originalText;


for (const entity of filteredEntities) {

  const start =
    entity.start;

  const end =
    entity.end;

  const type =
    String(entity.entity_type || "PII")
      .toUpperCase()
      .replace(/\s+/g, "_");

  const extractedText =
    entity.text;


  if (!extractedText) {
    continue;
  }


  // --------------------------------------------------------
  // REUSE EXISTING TOKEN
  // --------------------------------------------------------

  let token =
    Object.keys(mapping)
      .find(
        key =>
          mapping[key] ===
          extractedText
      );


  // --------------------------------------------------------
  // CREATE NEW TOKEN
  // --------------------------------------------------------

  if (!token) {

    counters[type] =
      (counters[type] || 0) + 1;

    token =
      `[${type}_${counters[type]}]`;

    mapping[token] =
      extractedText;
  }


  // --------------------------------------------------------
  // REPLACE RIGHT -> LEFT
  // --------------------------------------------------------

  modifiedText =
    modifiedText.substring(
      0,
      start
    ) +
    token +
    modifiedText.substring(
      end
    );
}


// ============================================================
// 8. OUTPUT
// ============================================================

return [
  {
    json: {

      deidentifiedText:
        modifiedText,

      mapping:
        mapping
    }
  }
];

