let combinedMapping = {};

// 1. جلب البيانات من De-identify
try {
    const deidNode = $('De-identify').first().json;
    if (deidNode && deidNode.mapping) {
        for (const [token, realValue] of Object.entries(deidNode.mapping)) {
            if (token && realValue) combinedMapping[token] = realValue;
        }
    }
} catch (e) {}

// 2. جلب البيانات من Regex detect
try {
    const regexNode = $('Regex detect').first().json;
    if (regexNode && regexNode.checks) {
        for (const check of regexNode.checks) {
            if (check.triggered && check.info && Array.isArray(check.info.analyzerResults)) {
                for (const result of check.info.analyzerResults) {
                    if (result.entityType && result.text) {
                        combinedMapping[`<${result.entityType}>`] = result.text;
                    }
                }
            }
        }
    }
} catch (e) {}

// 3. تحويل الكائن إلى مصفوفة مؤقتة للعمليات
const mappingArray = Object.entries(combinedMapping).map(([token, value]) => ({
    token: token,
    value: value
}));

// 4. بناء النص النهائي المنسق
const mappingText = mappingArray.length > 0 
    ? mappingArray.map(item => `• ${item.token}: ${item.value}`).join('\n')
    : "Not founded ";

// إرجاع النتيجة كنص مباشر (Text Output) بدلاً من Array
return {
    output: mappingText
};

